import sys

def query(u, v):
    print(f'? {u} {v}', flush=True)
    return int(sys.stdin.readline().strip())

n = int(sys.stdin.readline())
edges = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n - 1)]

# Find a leaf node
leaf = None
degree = [0] * (n + 1)
for u, v in edges:
    degree[u] += 1
    degree[v] += 1
    if degree[u] == 1:
        leaf = u
    if degree[v] == 1:
        leaf = v

# Find the furthest node from the leaf
farthest = leaf
current = leaf
while True:
    found = False
    for u, v in edges:
        if u == current and degree[v] > 1:
            current = v
            found = True
            break
        if v == current and degree[u] > 1:
            current = u
            found = True
            break
    if not found:
        break
    farthest = current

# Binary search for the root
low, high = 1, n
while low < high:
    mid = (low + high) // 2
    lca = query(farthest, mid)
    if lca == mid:
        low = mid + 1
    else:
        high = mid

print(f'! {high}', flush=True)
